// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        address adr = address(0x1234);
        uint256 initialBalance = 10 ether;
        vm.deal(address(c), initialBalance);
        vm.deal(address(this), 1 wei);
        vm.prank(address(this));
        c.Command{value: 1 wei}(adr, hex"");
        assertEq(adr.balance, 1 wei);
    }
}
